Here's a design for a fault-tolerant IoT Smart Grid Monitoring System in Python. This solution is decoupled into three isolated modules.

### Requirements
- Python 3.8 or later
- `json` library for parsing JSON telemetry streams
- `logging` library for system logging
- `requests` library for webhook notifications
- `concurrent.futures` library for concurrent processing

### Module 1: Sensor Data Ingestion Gateway

```python
# sensor_data_ingestion_gateway.py
import json
import logging
from typing import Dict

class SensorDataIngestionGateway:
    def __init__(self):
        self.logger = logging.getLogger(__name__)

    def parse_and_validate_telemetry(self, telemetry_stream: str) -> Dict:
        try:
            telemetry_data = json.loads(telemetry_stream)
            if 'voltage' in telemetry_data and isinstance(telemetry_data['voltage'], (int, float)):
                return telemetry_data
            else:
                self.logger.error("Invalid telemetry data: {}".format(telemetry_stream))
                return {}
        except json.JSONDecodeError as e:
            self.logger.error("Failed to parse telemetry data: {}".format(e))
            return {}

    def ingest_telemetry(self, telemetry_stream: str):
        parsed_telemetry = self.parse_and_validate_telemetry(telemetry_stream)
        if parsed_telemetry:
            yield parsed_telemetry

# Example usage:
if __name__ == "__main__":
    gateway = SensorDataIngestionGateway()
    telemetry_stream = '{"voltage": 230.5}'
    for telemetry in gateway.ingest_telemetry(telemetry_stream):
        print(telemetry)
```

### Module 2: Stream Processing Engine

```python
# stream_processing_engine.py
from collections import deque
from typing import Dict, Iterable
import logging

class StreamProcessingEngine:
    def __init__(self, window_size: int = 5, brownout_threshold: float = 200):
        self.logger = logging.getLogger(__name__)
        self.window_size = window_size
        self.brownout_threshold = brownout_threshold
        self.voltage_queue = deque(maxlen=window_size)

    def calculate_rolling_average(self, voltage: float):
        self.voltage_queue.append(voltage)
        return sum(self.voltage_queue) / len(self.voltage_queue)

    def detect_brownout(self, rolling_average: float):
        return rolling_average < self.brownout_threshold

    def process_stream(self, telemetry_stream: Iterable[Dict]):
        for telemetry in telemetry_stream:
            voltage = telemetry.get('voltage')
            if voltage is not None:
                rolling_average = self.calculate_rolling_average(voltage)
                if self.detect_brownout(rolling_average):
                    yield {
                        'rolling_average': rolling_average,
                        'brownout_detected': True
                    }
                else:
                    yield {
                        'rolling_average': rolling_average,
                        'brownout_detected': False
                    }

# Example usage:
if __name__ == "__main__":
    engine = StreamProcessingEngine()
    telemetry_stream = [
        {'voltage': 230.5},
        {'voltage': 220.5},
        {'voltage': 210.5},
        {'voltage': 200.5},
        {'voltage': 190.5},
    ]
    for result in engine.process_stream(telemetry_stream):
        print(result)
```

### Module 3: Alert Dispatcher

```python
# alert_dispatcher.py
import requests
import time
from typing import Dict

class AlertDispatcher:
    def __init__(self, webhook_url: str, initial_backoff: int = 1, max_backoff: int = 32):
        self.webhook_url = webhook_url
        self.initial_backoff = initial_backoff
        self.max_backoff = max_backoff
        self.backoff_multiplier = 2

    def dispatch_alert(self, alert_data: Dict):
        backoff = self.initial_backoff
        while True:
            try:
                response = requests.post(self.webhook_url, json=alert_data)
                response.raise_for_status()
                break
            except requests.RequestException as e:
                print(f"Failed to dispatch alert: {e}")
                if backoff < self.max_backoff:
                    time.sleep(backoff)
                    backoff *= self.backoff_multiplier
                else:
                    print("Max backoff reached. Giving up.")
                    break

# Example usage:
if __name__ == "__main__":
    dispatcher = AlertDispatcher('https://example.com/webhook')
    alert_data = {'brownout_detected': True, 'rolling_average': 190.5}
    dispatcher.dispatch_alert(alert_data)
```

### Integrating the Modules

To integrate these modules, you would need to create a data pipeline that flows from the `SensorDataIngestionGateway` to the `StreamProcessingEngine` and finally to the `AlertDispatcher`.

```python
# main.py
from sensor_data_ingestion_gateway import SensorDataIngestionGateway
from stream_processing_engine import StreamProcessingEngine
from alert_dispatcher import AlertDispatcher

def main():
    gateway = SensorDataIngestionGateway()
    engine = StreamProcessingEngine()
    dispatcher = AlertDispatcher('https://example.com/webhook')

    # Simulate a telemetry stream
    telemetry_stream = [
        '{"voltage": 230.5}',
        '{"voltage": 220.5}',
        '{"voltage": 210.5}',
        '{"voltage": 200.5}',
        '{"voltage": 190.5}',
    ]

    for telemetry in telemetry_stream:
        parsed_telemetry = next(gateway.ingest_telemetry(telemetry))
        for result in engine.process_stream([parsed_telemetry]):
            if result['brownout_detected']:
                dispatcher.dispatch_alert(result)

if __name__ == "__main__":
    main()
```

This code creates a simple data pipeline that ingests telemetry data, processes it, and dispatches alerts if a brownout is detected. Note that in a real-world scenario, you would need to handle errors and exceptions more robustly, and add additional features such as data storage and visualization.
